import { TruncatePipe } from './truncate.pipe';

describe('TruncatePipe', () => {
  const pipe = new TruncatePipe();

  it('should return the same string if length <= maxLength', () => {
    expect(pipe.transform('Hello', 10)).toBe('Hello');
    expect(pipe.transform('Hello', 5)).toBe('Hello');
  });

  it('should truncate and append "..." if string is longer', () => {
    expect(pipe.transform('Hello World', 5)).toBe('Hello...');
    expect(pipe.transform('abcdef', 3)).toBe('abc...');
  });

  it('should return empty string for null/undefined', () => {
    expect(pipe.transform(null)).toBe('');
    expect(pipe.transform(undefined)).toBe('');
  });

  it('should use default maxLength of 20 if not provided', () => {
    const longStr = 'a'.repeat(25);
    expect(pipe.transform(longStr)).toBe('a'.repeat(20) + '...');
  });
});
